{
  "name": "opencode-court",
  "version": "0.1.3",
  "description": "朝廷编队 —— OpenCode 的 18 角色官制多 agent 协作插件(定向异步通信 + 跳数预算)",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    }
  },
  "files": [
    "dist",
    "agents",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "gen:agents": "bun run scripts/gen-agents.ts",
    "test": "bun test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "multi-agent",
    "orchestration",
    "ai-agent"
  ],
  "license": "GPL-2.0-or-later",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/node": "^26.6.6",
    "typescript": "^5.6.0"
  },
  "bin": {
    "opencode-court": "dist/cli.js"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/fcf147/opencode-court.git"
  },
  "homepage": "https://github.com/fcf147/opencode-court#readme",
  "bugs": {
    "url": "https://github.com/fcf147/opencode-court/issues"
  },
  "author": "fcf147",
  "engines": {
    "node": ">=18"
  }
}
